<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Personal Expense Tracker</title>
<style>
  * { box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; margin: 0; padding: 20px; background: #f5f5f5; color: #222; }
  .container { max-width: 700px; margin: 0 auto; background: #fff; padding: 20px; border: 1px solid #ddd; border-radius: 8px; }
  h1 { margin-top: 0; }
  form { display: grid; gap: 10px; margin-bottom: 10px; }
  label { display: flex; flex-direction: column; gap: 4px; font-size: 14px; }
  input, select, button { padding: 8px; font-size: 14px; }
  #add-expense { cursor: pointer; }
  #form-error { min-height: 1.2em; color: #b00020; font-size: 14px; }
  .filters { display: flex; gap: 10px; flex-wrap: wrap; margin: 16px 0; padding: 10px; background: #fafafa; border: 1px solid #eee; border-radius: 6px; }
  .filters label { flex: 1; min-width: 140px; }
  .summary { margin: 12px 0; padding: 10px; background: #f0f6ff; border-radius: 6px; }
  #total { font-weight: bold; }
  #category-totals { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 8px; }
  .cat-total { background: #fff; border: 1px solid #ddd; padding: 6px 10px; border-radius: 4px; font-size: 14px; }
  #expense-list { display: flex; flex-direction: column; gap: 8px; margin-top: 12px; }
  .expense { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 1px solid #ddd; border-radius: 6px; background: #fff; }
  .expense span { flex: 1; }
  .exp-amount { font-weight: bold; }
  .exp-del { cursor: pointer; }
</style>
</head>
<body>
<div class="container">
  <h1>Personal Expense Tracker</h1>

  <form id="expense-form" novalidate>
    <label>Amount
      <input type="number" id="amount" step="0.01" min="0" placeholder="e.g. 25.50">
    </label>
    <label>Category
      <select id="category">
        <option value="groceries">groceries</option>
        <option value="transport">transport</option>
        <option value="bills">bills</option>
        <option value="fun">fun</option>
      </select>
    </label>
    <label>Date
      <input type="date" id="date">
    </label>
    <label>Note (optional)
      <input type="text" id="note" placeholder="optional note">
    </label>
    <button type="submit" id="add-expense">Add Expense</button>
    <div id="form-error" aria-live="polite"></div>
  </form>

  <div class="filters">
    <label>Filter by category
      <select id="filter-category">
        <option value="all">all</option>
        <option value="groceries">groceries</option>
        <option value="transport">transport</option>
        <option value="bills">bills</option>
        <option value="fun">fun</option>
      </select>
    </label>
    <label>From
      <input type="date" id="filter-from">
    </label>
    <label>To
      <input type="date" id="filter-to">
    </label>
  </div>

  <div class="summary">
    <div>Total: <span id="total">0.00</span></div>
    <div id="category-totals">
      <div class="cat-total" data-cat="groceries">groceries: 0.00</div>
      <div class="cat-total" data-cat="transport">transport: 0.00</div>
      <div class="cat-total" data-cat="bills">bills: 0.00</div>
      <div class="cat-total" data-cat="fun">fun: 0.00</div>
    </div>
  </div>

  <div id="expense-list"></div>
</div>

<script>
(function() {
  var STORAGE_KEY = 'personal-expenses-v1';
  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

  var amountEl = document.getElementById('amount');
  var categoryEl = document.getElementById('category');
  var dateEl = document.getElementById('date');
  var noteEl = document.getElementById('note');
  var form = document.getElementById('expense-form');
  var formError = document.getElementById('form-error');
  var listEl = document.getElementById('expense-list');
  var totalEl = document.getElementById('total');
  var filterCategoryEl = document.getElementById('filter-category');
  var filterFromEl = document.getElementById('filter-from');
  var filterToEl = document.getElementById('filter-to');

  var expenses = [];

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          expenses = parsed.filter(function(e) {
            return e && typeof e.amount === 'number' && typeof e.category === 'string' && typeof e.date === 'string';
          });
        }
      }
    } catch (e) {
      expenses = [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (e) {}
  }

  function isVisible(exp) {
    var fCat = filterCategoryEl.value;
    var from = filterFromEl.value;
    var to = filterToEl.value;
    if (fCat && fCat !== 'all' && exp.category !== fCat) return false;
    if (from && exp.date < from) return false;
    if (to && exp.date > to) return false;
    return true;
  }

  function render() {
    listEl.innerHTML = '';
    expenses.forEach(function(exp) {
      var row = document.createElement('div');
      row.className = 'expense';
      row.dataset.id = exp.id;

      var amt = document.createElement('span');
      amt.className = 'exp-amount';
      amt.textContent = Number(exp.amount).toFixed(2);

      var cat = document.createElement('span');
      cat.className = 'exp-category';
      cat.textContent = exp.category;

      var dt = document.createElement('span');
      dt.className = 'exp-date';
      dt.textContent = exp.date;

      var nt = document.createElement('span');
      nt.className = 'exp-note';
      nt.textContent = exp.note || '';

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'exp-del';
      del.textContent = 'Delete';
      del.addEventListener('click', function() {
        deleteExpense(exp.id);
      });

      row.appendChild(amt);
      row.appendChild(cat);
      row.appendChild(dt);
      row.appendChild(nt);
      row.appendChild(del);

      if (!isVisible(exp)) {
        row.style.display = 'none';
      } else {
        row.style.display = '';
      }

      listEl.appendChild(row);
    });
    updateTotals();
  }

  function updateTotals() {
    var visible = expenses.filter(isVisible);
    var sum = visible.reduce(function(acc, e) { return acc + Number(e.amount); }, 0);
    totalEl.textContent = sum.toFixed(2);

    CATEGORIES.forEach(function(c) {
      var el = document.querySelector('.cat-total[data-cat="' + c + '"]');
      if (!el) return;
      var cSum = visible.filter(function(e) { return e.category === c; })
        .reduce(function(acc, e) { return acc + Number(e.amount); }, 0);
      el.textContent = c + ': ' + cSum.toFixed(2);
    });
  }

  function deleteExpense(id) {
    expenses = expenses.filter(function(e) { return String(e.id) !== String(id); });
    save();
    render();
  }

  function handleSubmit(e) {
    if (e) e.preventDefault();
    var amountStr = amountEl.value.trim();
    var dateVal = dateEl.value;
    var catVal = categoryEl.value;
    var noteVal = noteEl.value;

    var amountNum = parseFloat(amountStr);

    if (amountStr === '' || isNaN(amountNum) || !isFinite(amountNum) || amountNum <= 0) {
      formError.textContent = 'Please enter a valid amount greater than zero.';
      return;
    }
    if (!dateVal) {
      formError.textContent = 'Please select a date.';
      return;
    }

    var exp = {
      id: Date.now().toString(36) + Math.random().toString(36).slice(2),
      amount: amountNum,
      category: catVal,
      date: dateVal,
      note: noteVal ? noteVal.trim() : '',
      createdAt: Date.now()
    };

    expenses.unshift(exp);
    save();
    render();

    formError.textContent = '';
    amountEl.value = '';
    noteEl.value = '';
    amountEl.focus();
  }

  form.addEventListener('submit', handleSubmit);

  [filterCategoryEl, filterFromEl, filterToEl].forEach(function(el) {
    el.addEventListener('change', render);
    el.addEventListener('input', render);
  });

  load();
  render();
})();
</script>
</body>
</html>
